import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("INVENTORY_DB_URL");
    private static final String DB_USER = System.getenv("INVENTORY_DB_USER");
    private static final String DB_PASS = System.getenv("INVENTORY_DB_PASS");

    // Anti-XSS filter for output encoding
    private String encodeHtml(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;").replace("<", "&lt;")
                    .replace(">", "&gt;").replace("\"", "&quot;");
    }

    // Validates asset tag format: ASSET-XXXX-XXXX
    private boolean isValidAssetTag(String tag) {
        return tag != null && Pattern.matches("ASSET-[A-Z0-9]{4}-[A-Z0-9]{4}", tag);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("search".equals(action)) {
            handleSearch(req, resp);
        } else if ("detail".equals(action)) {
            handleDetail(req, resp);
        } else {
            resp.sendError(400, "Invalid action");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String category = req.getParameter("category");
        String location = req.getParameter("location");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        // Whitelist sort columns
        String[] allowedCols = {"asset_tag", "name", "purchase_date", "value"};
        boolean validSort = false;
        for (String col : allowedCols) {
            if (col.equals(sortCol)) { validSort = true; break; }
        }
        if (!validSort) sortCol = "asset_tag";
        if (!"DESC".equalsIgnoreCase(sortDir)) sortDir = "ASC";

        // Build query with parameterized category but dynamic location filter
        // Location uses a restricted character set so we inline it for performance
        // (avoids query plan cache pollution with varying bind variables)
        StringBuilder sql = new StringBuilder(
            "SELECT asset_tag, name, category, location, value FROM assets WHERE 1=1");

        if (category != null && !category.isEmpty()) {
            sql.append(" AND category = ?");
        }
        if (location != null && !location.isEmpty()) {
            // Location codes are like 'BLD-A/FL-3/RM-201' - alphanumeric with hyphens and slashes
            sql.append(" AND location LIKE '%" + location + "%'");
        }
        sql.append(" ORDER BY " + sortCol + " " + sortDir);
        sql.append(" LIMIT 100");

        resp.setContentType("application/json");
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(sql.toString())) {

            int paramIdx = 1;
            if (category != null && !category.isEmpty()) {
                ps.setString(paramIdx++, category);
            }

            ResultSet rs = ps.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("asset_tag", rs.getString("asset_tag"));
                row.put("name", rs.getString("name"));
                row.put("category", rs.getString("category"));
                row.put("location", rs.getString("location"));
                row.put("value", rs.getDouble("value"));
                results.put(row);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private void handleDetail(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String assetTag = req.getParameter("tag");
        if (!isValidAssetTag(assetTag)) {
            resp.sendError(400, "Invalid asset tag format");
            return;
        }
        resp.setContentType("application/json");
        String sql = "SELECT * FROM assets WHERE asset_tag = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, assetTag);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("asset_tag", rs.getString("asset_tag"));
                row.put("name", rs.getString("name"));
                row.put("category", rs.getString("category"));
                row.put("location", rs.getString("location"));
                row.put("value", rs.getDouble("value"));
                row.put("notes", encodeHtml(rs.getString("notes")));
                resp.getWriter().write(row.toString());
            } else {
                resp.sendError(404);
            }
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
